import json

with open('/app/analysis.json') as f:
    d = json.load(f)

def fmt_money(v): return f"${v:,.0f}"
def fmt_money2(v): return f"${v:,.2f}"
def fmt_pct(v): return f"{v:.1f}%"
def fmt_int(v): return f"{int(v):,}"

# Monthly series
months_labels = [m['label'] for m in d['monthly']]
months_rev = [round(m['revenue'],2) for m in d['monthly']]
months_profit = [round(m['profit'],2) for m in d['monthly']]
months_orders = [m['orders'] for m in d['monthly']]

# 2023 vs 2024 by month for YoY comparison
m2023 = {m['month']: m for m in d['monthly'] if m['year']==2023}
m2024 = {m['month']: m for m in d['monthly'] if m['year']==2024}
month_names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
rev_2023_m = [round(m2023[i]['revenue'],2) if i in m2023 else 0 for i in range(1,13)]
rev_2024_m = [round(m2024[i]['revenue'],2) if i in m2024 else 0 for i in range(1,13)]

# Quarterly
qtr_labels = [q['quarter'] for q in d['quarterly']]
qtr_rev = [round(q['revenue'],2) for q in d['quarterly']]
qtr_profit = [round(q['profit'],2) for q in d['quarterly']]

# Discount tiers
dt_labels = [t['disc_tier'] for t in d['discount_tiers']]
dt_orders = [t['orders'] for t in d['discount_tiers']]
dt_revenue = [round(t['revenue'],2) for t in d['discount_tiers']]
dt_margin = [round(t['margin'],2) for t in d['discount_tiers']]
dt_aov = [round(t['avg_order_value'],2) for t in d['discount_tiers']]

# Top products
tp = d['top_products']
# Top stores
ts = d['top_stores']

# Customer segments
cs = d['customer_segments']

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Chocolate Retail Sales Performance Report — 2023-2024</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --brand: #3B1F0F;
    --accent: #B8862F;
    --accent-light: #E8C583;
    --ink: #1F1A17;
    --muted: #6B625A;
    --bg: #FAF7F2;
    --card: #FFFFFF;
    --border: #E7DFD3;
    --good: #2E7D5B;
    --bad: #C24A3A;
  }}
  * {{ box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    margin: 0;
    line-height: 1.55;
  }}
  .wrap {{ max-width: 1200px; margin: 0 auto; padding: 40px 32px 80px; }}
  header.hero {{
    background: linear-gradient(135deg, #3B1F0F 0%, #5C3A1E 100%);
    color: #fff;
    padding: 56px 48px;
    border-radius: 14px;
    margin-bottom: 32px;
    box-shadow: 0 8px 24px rgba(59,31,15,0.15);
  }}
  header.hero .eyebrow {{
    font-size: 12px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--accent-light);
    font-weight: 600;
  }}
  header.hero h1 {{
    font-size: 38px;
    margin: 12px 0 8px;
    font-weight: 700;
    letter-spacing: -0.5px;
  }}
  header.hero p.sub {{ color: #E8DCC7; font-size: 16px; max-width: 720px; margin: 0; }}
  header.hero .meta {{
    margin-top: 24px;
    font-size: 13px;
    color: #D6C4A5;
    display: flex;
    gap: 28px;
    flex-wrap: wrap;
  }}
  h2.section {{
    font-size: 26px;
    color: var(--brand);
    border-left: 4px solid var(--accent);
    padding-left: 14px;
    margin: 48px 0 20px;
    font-weight: 700;
  }}
  h3 {{ font-size: 17px; color: var(--brand); margin: 24px 0 12px; font-weight: 600; }}
  p, li {{ font-size: 14.5px; color: var(--ink); }}
  p.lede {{ font-size: 15.5px; color: #2B241E; }}
  .card {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 18px;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin: 8px 0 24px;
  }}
  .kpi {{
    background: var(--card);
    border: 1px solid var(--border);
    border-top: 4px solid var(--accent);
    border-radius: 10px;
    padding: 18px 18px 20px;
  }}
  .kpi .lbl {{
    font-size: 11.5px;
    color: var(--muted);
    letter-spacing: 1.2px;
    text-transform: uppercase;
    font-weight: 600;
  }}
  .kpi .val {{
    font-size: 26px;
    font-weight: 700;
    color: var(--brand);
    margin: 6px 0 2px;
    letter-spacing: -0.5px;
  }}
  .kpi .sub {{ font-size: 12px; color: var(--muted); }}
  .kpi.primary {{ border-top-color: var(--brand); background: #FFF9ED; }}
  .grid-2 {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .chart-box {{
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px 14px;
    margin: 14px 0;
  }}
  .chart-box h4 {{ margin: 0 0 12px; font-size: 15px; color: var(--brand); font-weight: 600; }}
  .chart-wrap {{ position: relative; height: 320px; }}
  .chart-wrap.tall {{ height: 380px; }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
    margin: 10px 0;
  }}
  th, td {{ padding: 10px 12px; text-align: right; border-bottom: 1px solid var(--border); }}
  th:first-child, td:first-child {{ text-align: left; }}
  thead th {{
    background: #F5EFE4;
    color: var(--brand);
    font-weight: 600;
    font-size: 12.5px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-bottom: 2px solid var(--accent);
  }}
  tbody tr:hover {{ background: #FBF7EE; }}
  .trend-up {{ color: var(--good); font-weight: 600; }}
  .trend-down {{ color: var(--bad); font-weight: 600; }}
  .callout {{
    background: #FFF6E4;
    border-left: 4px solid var(--accent);
    padding: 14px 18px;
    border-radius: 6px;
    margin: 14px 0;
    font-size: 14px;
  }}
  .caveat {{
    background: #F3EFEA;
    border-left: 3px solid var(--muted);
    padding: 10px 14px;
    border-radius: 4px;
    margin: 12px 0;
    font-size: 13px;
    color: #4A433C;
  }}
  .insight-list {{ margin: 10px 0; padding-left: 20px; }}
  .insight-list li {{ margin-bottom: 8px; }}
  footer {{ text-align: center; margin-top: 48px; font-size: 12px; color: var(--muted); }}
  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .grid-2 {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>
<div class="wrap">

<header class="hero">
  <div class="eyebrow">Retail Analytics · FY 2023–2024</div>
  <h1>Chocolate Retail Sales Performance Report</h1>
  <p class="sub">A comprehensive two-year review of revenue, profitability, product mix, promotional effectiveness, and customer behavior — prepared for retail management to inform FY planning.</p>
  <div class="meta">
    <div><strong>Period:</strong> {d['date_min']} → {d['date_max']}</div>
    <div><strong>Transactions:</strong> {fmt_int(d['total_orders'])}</div>
    <div><strong>Stores:</strong> {d['total_stores']}</div>
    <div><strong>Products:</strong> {d['unique_products']}</div>
    <div><strong>Customers:</strong> {fmt_int(d['unique_customers'])}</div>
  </div>
</header>

<!-- EXECUTIVE SUMMARY -->
<h2 class="section">Executive Summary</h2>
<p class="lede">Over the 2023–2024 period, the business generated <strong>{fmt_money(d['total_revenue'])}</strong> in revenue and <strong>{fmt_money(d['total_profit'])}</strong> in profit on {fmt_int(d['total_orders'])} transactions, holding a healthy <strong>{fmt_pct(d['overall_profit_margin'])}</strong> profit margin. Revenue grew <strong>{d['rev_yoy']:+.1f}%</strong> year-over-year — modest momentum that warrants focus on growth levers in FY planning.</p>

<div class="kpi-grid">
  <div class="kpi primary">
    <div class="lbl">Total Revenue</div>
    <div class="val">{fmt_money(d['total_revenue'])}</div>
    <div class="sub">2023–2024 combined</div>
  </div>
  <div class="kpi primary">
    <div class="lbl">Total Profit</div>
    <div class="val">{fmt_money(d['total_profit'])}</div>
    <div class="sub">Revenue minus cost</div>
  </div>
  <div class="kpi primary">
    <div class="lbl">Avg Profit Margin</div>
    <div class="val">{fmt_pct(d['avg_profit_margin'])}</div>
    <div class="sub">Mean transaction margin</div>
  </div>
  <div class="kpi">
    <div class="lbl">Avg Order Value</div>
    <div class="val">{fmt_money2(d['avg_order_value'])}</div>
    <div class="sub">Per transaction</div>
  </div>
  <div class="kpi">
    <div class="lbl">Discount Utilization</div>
    <div class="val">{fmt_pct(d['discount_util_rate'])}</div>
    <div class="sub">Orders with a discount</div>
  </div>
</div>

<div class="card">
  <h3>Headline Findings</h3>
  <ul class="insight-list">
    <li><strong>Flat growth trajectory.</strong> Revenue rose <span class="trend-up">{d['rev_yoy']:+.1f}%</span> YoY and profit <span class="trend-up">{d['profit_yoy']:+.1f}%</span> — the business is stable but not expanding. Breaking out of flat requires either category-level promotion, underperforming-store intervention, or customer reactivation.</li>
    <li><strong>Margins are remarkably consistent.</strong> Across every discount tier, profit margin holds near {fmt_pct(d['overall_profit_margin'])}. This indicates pricing discipline but also suggests current discount depths are not driving incremental margin benefit.</li>
    <li><strong>Customer concentration is moderate.</strong> The top 10% of customers account for {fmt_pct(d['top_10pct_cust_rev_share'])} of revenue, with average customer revenue at {fmt_money2(d['avg_revenue_per_cust'])} across {d['avg_orders_per_cust']:.2f} orders.</li>
    <li><strong>Promotional volume lift is unclear.</strong> Average quantity per transaction is effectively identical (~3.0 units) across discounted and non-discounted orders — indicating discounts currently do not materially drive unit uplift.</li>
  </ul>
</div>

<div class="grid-2">
  <div class="chart-box">
    <h4>Revenue by Year</h4>
    <div class="chart-wrap"><canvas id="yearlyRev"></canvas></div>
  </div>
  <div class="chart-box">
    <h4>Profit by Year</h4>
    <div class="chart-wrap"><canvas id="yearlyProfit"></canvas></div>
  </div>
</div>

<!-- SALES TRENDS -->
<h2 class="section">Sales Trends Over Time</h2>
<p class="lede">Monthly and quarterly momentum reveals the shape of demand across the two-year window. The charts below make seasonality and year-over-year dynamics immediately visible.</p>

<div class="chart-box">
  <h4>Monthly Revenue — 2023 vs 2024 (YoY comparison)</h4>
  <div class="chart-wrap tall"><canvas id="monthlyYoY"></canvas></div>
</div>

<div class="chart-box">
  <h4>Monthly Revenue & Profit Trend (24-month series)</h4>
  <div class="chart-wrap tall"><canvas id="monthlyTrend"></canvas></div>
</div>

<div class="grid-2">
  <div class="chart-box">
    <h4>Quarterly Revenue</h4>
    <div class="chart-wrap"><canvas id="quarterly"></canvas></div>
  </div>
  <div class="chart-box">
    <h4>Monthly Order Volume</h4>
    <div class="chart-wrap"><canvas id="monthlyOrders"></canvas></div>
  </div>
</div>

<div class="callout">
  <strong>Trend read-out.</strong> 2023 revenue closed at {fmt_money(d['yearly'][0]['revenue'])} ({fmt_int(d['yearly'][0]['orders'])} orders); 2024 closed at {fmt_money(d['yearly'][1]['revenue'])} ({fmt_int(d['yearly'][1]['orders'])} orders). Month-to-month volatility is narrow — the business does not exhibit sharp seasonal spikes in this dataset, which is atypical for chocolate retail. Management should verify whether holiday-season signal is present in source systems (the fact table alone may smooth across promotional windows).
</div>

<!-- PRODUCT PERFORMANCE -->
<h2 class="section">Product &amp; Category Performance</h2>
<p class="lede">With {d['unique_products']} distinct SKUs in circulation, product-level contribution to revenue and profit varies meaningfully. The top 10 products below represent the revenue anchors of the catalog.</p>

<div class="caveat">
  <strong>Data scope note:</strong> The provided fact table contains product IDs but not brand, category, or cocoa-percentage attributes (the referenced <code>products.csv</code> dimension table was not supplied in this analysis input). Category-, brand-, and cocoa-% level breakdowns have therefore been omitted rather than fabricated. Attaching the product dimension would unlock those cuts.
</div>

<div class="chart-box">
  <h4>Top 10 Products by Revenue</h4>
  <div class="chart-wrap tall"><canvas id="topProducts"></canvas></div>
</div>

<div class="card">
  <h3>Top 10 Products — Detail</h3>
  <table>
    <thead><tr><th>Product ID</th><th>Revenue</th><th>Profit</th><th>Margin</th><th>Units Sold</th><th>Orders</th></tr></thead>
    <tbody>
"""
for p in tp:
    html += f"      <tr><td>{p['product_id']}</td><td>{fmt_money2(p['revenue'])}</td><td>{fmt_money2(p['profit'])}</td><td>{fmt_pct(p['margin'])}</td><td>{fmt_int(p['units'])}</td><td>{fmt_int(p['orders'])}</td></tr>\n"

html += f"""    </tbody>
  </table>
</div>

<div class="card">
  <h3>Bottom 5 Products by Revenue</h3>
  <p>The lowest-revenue SKUs below are candidates for range-review: whether to refresh packaging, reposition pricing, or phase out in favor of higher-rotation items.</p>
  <table>
    <thead><tr><th>Product ID</th><th>Revenue</th><th>Profit</th><th>Margin</th><th>Orders</th></tr></thead>
    <tbody>
"""
for p in d['bottom_products']:
    html += f"      <tr><td>{p['product_id']}</td><td>{fmt_money2(p['revenue'])}</td><td>{fmt_money2(p['profit'])}</td><td>{fmt_pct(p['margin'])}</td><td>{fmt_int(p['orders'])}</td></tr>\n"

html += f"""    </tbody>
  </table>
</div>

<!-- STORE ANALYSIS -->
<h2 class="section">Store &amp; Geographic Performance</h2>
<p class="lede">{d['total_stores']} retail locations contributed to total revenue. The distribution below highlights the top and bottom performers — management's primary levers for either scaling winning-store playbooks or remediating underperformers.</p>

<div class="caveat">
  <strong>Data scope note:</strong> Store-level attributes (city, country, store type) from the <code>stores.csv</code> dimension were not provided with the analysis input. Geographic and store-type cuts are therefore unavailable in this report; only store-ID-level aggregates are shown. Attaching store dimension data would enable country, city, and store-type comparisons.
</div>

<div class="chart-box">
  <h4>Top 10 Stores by Revenue</h4>
  <div class="chart-wrap tall"><canvas id="topStores"></canvas></div>
</div>

<div class="grid-2">
  <div class="card">
    <h3>Top 10 Stores</h3>
    <table>
      <thead><tr><th>Store</th><th>Revenue</th><th>Margin</th><th>Orders</th></tr></thead>
      <tbody>
"""
for s in ts:
    html += f"        <tr><td>{s['store_id']}</td><td>{fmt_money2(s['revenue'])}</td><td>{fmt_pct(s['margin'])}</td><td>{fmt_int(s['orders'])}</td></tr>\n"

html += f"""      </tbody>
    </table>
  </div>
  <div class="card">
    <h3>Bottom 5 Stores</h3>
    <table>
      <thead><tr><th>Store</th><th>Revenue</th><th>Margin</th><th>Orders</th></tr></thead>
      <tbody>
"""
for s in d['bottom_stores']:
    html += f"        <tr><td>{s['store_id']}</td><td>{fmt_money2(s['revenue'])}</td><td>{fmt_pct(s['margin'])}</td><td>{fmt_int(s['orders'])}</td></tr>\n"

top_store_rev = ts[0]['revenue']
bot_store_rev = d['bottom_stores'][0]['revenue']
html += f"""      </tbody>
    </table>
  </div>
</div>

<div class="callout">
  <strong>Spread between top and bottom is wide.</strong> Top store generates {fmt_money2(top_store_rev)} vs bottom-ranked at {fmt_money2(bot_store_rev)} — a {top_store_rev/bot_store_rev:.1f}× gap. A next step is to pair each bottom-quartile store with a top-quartile mentor store and audit assortment + staffing alignment.
</div>

<!-- DISCOUNT ANALYSIS -->
<h2 class="section">Discount Impact &amp; Profitability Analysis</h2>
<p class="lede">Discounts were applied on <strong>{fmt_pct(d['discount_util_rate'])}</strong> of transactions. The critical question for management: do discounts drive incremental value, or do they erode margin without producing offsetting volume?</p>

<div class="grid-2">
  <div class="chart-box">
    <h4>Revenue &amp; Profit by Discount Tier</h4>
    <div class="chart-wrap"><canvas id="discRev"></canvas></div>
  </div>
  <div class="chart-box">
    <h4>Profit Margin by Discount Tier</h4>
    <div class="chart-wrap"><canvas id="discMargin"></canvas></div>
  </div>
</div>

<div class="chart-box">
  <h4>Average Order Value by Discount Tier</h4>
  <div class="chart-wrap"><canvas id="discAOV"></canvas></div>
</div>

<div class="card">
  <h3>Discount Tier Detail</h3>
  <table>
    <thead><tr><th>Discount Tier</th><th>Orders</th><th>Order Share</th><th>Revenue</th><th>Profit</th><th>Margin</th><th>Avg Order Value</th><th>Avg Qty</th></tr></thead>
    <tbody>
