    gap: 14px;
    margin: 8px 0 24px;
  }}
  .kpi {{
    background: var(--card);
    border: 1px solid var(--border);
    border-top: 4px solid var(--accent);
    border-radius: 10px;
    padding: 18px 18px 20px;
  }}
  .kpi .lbl {{
    font-size: 11.5px;
